        if (s == null) {
            return 0;
        }
    }
    String first = strings.get(0);
    int maxLen = first.length();
    // Precompute reverse of first string for efficiency
    String revFirst = new StringBuilder(first).reverse().toString();
    // Helper to reverse a string
    java.util.function.Function<String, String> rev = str -> new StringBuilder(str).reverse().toString();
    // Iterate lengths from longest to shortest
    for (int len = maxLen; len >= 1; len--) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        // Generate all substrings of length len from first string
        for (int i = 0; i + len <= first.length(); i++) {
            String sub = first.substring(i, i + len);
            // Candidate X = sub
            if (seen.add(sub)) {
                if (checkCandidate(sub, strings, rev)) {
                    return len;
                }
            }
            // Candidate X = reverse(sub)
            String revSub = rev.apply(sub);
            if (seen.add(revSub)) {
                if (checkCandidate(revSub, strings, rev)) {
                    return len;
                }
            }
        }
    }
    return 0;
}

