public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Set<Integer> set = new java.util.HashSet<>();
    int zerosCount = 0;
    for (int num : numbers) {
        set.add(num);
        if (num == 0) {
            zerosCount++;
        }
    }
    int count = 0;
    for (int num : numbers) {
        if (num == 0) {
            if (zerosCount > 1) {
                count++;
            }
        } else if ((num & 1) == 0) { // even numbers
            int half = num / 2;
            if (set.contains(half)) {
                count++;
            }
        }
    }
    return count;
}

