public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0) {
        return "cannot be travelled";
    }
    if (start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // Helper to convert coordinate to string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                // Skip invalid path entries
                continue;
            }
            int[] coord1 = new int[n];
            int[] coord2 = new int[n];
            System.arraycopy(path, 0, coord1, 0, n);
            System.arraycopy(path, n, coord2, 0, n);
            String key1 = coordToKey.apply(coord1);
            String key2 = coordToKey.apply(coord2);
            adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
            adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
        }
    }
    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.get(current);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

