public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int k = n / 20; // number of elements to trim from each side
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    return sum / (double) (n - 2 * k);
}

