public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0) {
        return true;
    }
    if (k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r < k - r; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

