        return 0;
    }
    if (edges == null || edges.length != Math.max(0, n - 1)) {
        return 0;
    }
    // Build adjacency list
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            continue;
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue;
        }
        graph[u].add(v);
        graph[v].add(u);
    }

    boolean[] visited = new boolean[n];
    return dfs(0, graph, hasApple, visited);
}

