public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    dp[0] = new HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate k in reverse to avoid using updated values in the same iteration
        int maxK = Math.min(n / 2, n); // we only need up to n/2
        for (int k = maxK; k >= 1; k--) {
            if (dp[k - 1] == null) continue;
            if (dp[k] == null) dp[k] = new HashSet<>();
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((long) totalSum * k % n != 0) continue;
        int target = (int) ((long) totalSum * k / n);
        if (dp[k] != null && dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

