public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0) {
        return false;
    }
    int n = s.length();
    if (k == 0) {
        // Only one binary string of length 0: the empty string, which is always a substring
        return true;
    }
    if (n < k) {
        return false;
    }
    int total = 1 << k; // number of possible binary strings of length k
    // Use a boolean array if k is small enough, otherwise use a HashSet
    if (k <= 20) { // 2^20 = 1,048,576, manageable
        boolean[] seen = new boolean[total];
        int mask = 0;
        int maskLimit = total - 1;
        for (int i = 0; i < n; i++) {
            mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen[mask] = true;
            }
        }
        for (boolean b : seen) {
            if (!b) {
                return false;
            }
        }
        return true;
    } else {
        java.util.HashSet<Integer> seen = new java.util.HashSet<>(total);
        int mask = 0;
        int maskLimit = total - 1;
        for (int i = 0; i < n; i++) {
            mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen.add(mask);
                if (seen.size() == total) {
                    return true;
                }
            }
        }
        return seen.size() == total;
    }
}

