public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    int count = 0;
    int remaining = k;
    // Greedy: subtract the largest Fibonacci number <= remaining
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (fib <= remaining) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

