public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return k == 0 ? "" : "";
    }
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - minSum; // how much we need to add to reach k
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to this position
        sb.setCharAt(i, (char) ('a' + add));
        remaining -= add;
    }
    return sb.toString();
}

