public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    // Determine if the number is negative
    boolean negative = n < 0;
    // Work with absolute value to simplify processing
    long absValue = Math.abs((long) n);

    // Convert to string for easier manipulation
    String numberStr = Long.toString(absValue);
    StringBuilder sb = new StringBuilder();

    // Insert dots every three digits from the right
    int len = numberStr.length();
    int count = 0;
    for (int i = len - 1; i >= 0; i--) {
        sb.append(numberStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Reverse to get the correct order
    sb.reverse();

    // Prepend negative sign if needed
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

