public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to 200
    boolean[] isSquare = new boolean[201];
    for (int i = 0; i * i <= 200; i++) {
        isSquare[i * i] = true;
    }
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            if (mask == fullMask) return 1;
            if (last != -1 && memo[mask][last] != -1) return memo[mask][last];
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (last != -1 && !isSquare[A[last] + A[i]]) continue;
                // Skip duplicates: if current value equals previous and previous not used
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                count += applyAsInt(mask | (1 << i), i);
            }
            if (last != -1) memo[mask][last] = count;
            return count;
        }
    };
    // Start with no last element
    int total = 0;
    for (int i = 0; i < n; i++) {
        // Skip duplicates at the first position
        if (i > 0 && A[i] == A[i - 1]) continue;
        total += dfs.applyAsInt(1 << i, i);
    }
    return total;
}

