public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = 0;
    // Determine the maximum row length to handle jagged arrays
    for (int[] row : mat) {
        if (row != null && row.length > n) {
            n = row.length;
        }
    }
    if (n == 0) {
        return new int[0];
    }
    int total = 0;
    for (int[] row : mat) {
        if (row != null) {
            total += row.length;
        }
    }
    int[] result = new int[total];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        for (int i = 0; i < m; i++) {
            int j = sum - i;
            if (j < 0 || j >= n) {
                continue;
            }
            int[] row = mat[i];
            if (row == null || j >= row.length) {
                continue;
            }
            result[idx++] = row[j];
        }
    }
    return result;
}

