public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }
    // Check if n can be expressed as sum of two perfect squares
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - i * i;
        int sqrtRem = (int) Math.sqrt(remainder);
        if (sqrtRem * sqrtRem == remainder) {
            return 2;
        }
    }
    // Apply Legendre's three-square theorem
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    return 3;
}

